// DEV-ONLY design fixtures for /api/insights/*. Loaded by ./api only when
// `import.meta.env.DEV && localStorage["claudio.fixtures"] === "1"` (the import is constant-folded away in production).
// The samples below are trimmed and reshaped from real GMGN responses recorded on 2026-10-08 ($CLAUDIO holders and
// traders, KOL / smart-money trades, signals, the 1h rank and hot searches); times are shifted so they read as "just now".
// Extra switches: localStorage["claudio.fixtures.empty"] = "1" answers like an unavailable backend (404) everywhere;
// ["claudio.fixtures.partial"] = "1" returns the fast token set with `partial` set and no security / dev data.
// Pure module (no DOM): scripts can import it to stub the API in a production build.
import type {
  DevProfile,
  FeedSignal,
  FeedTrade,
  HolderRow,
  InsightsStatus,
  Score,
  TokenInsights,
  TokenScores,
  WalletProfile,
} from "@shared/insights";
import type { BoardToken } from "./board";

interface RawFeed extends Omit<FeedTrade, "at"> {
  atSec: number;
}
interface RawSignal extends Omit<FeedSignal, "at"> {
  atSec: number;
}
interface RawFixtures {
  recordedAtSec: number;
  holders: HolderRow[];
  traders: HolderRow[];
  insights: Omit<TokenInsights, "key" | "chain" | "address" | "signals" | "source" | "updatedAt">;
  devCoins: DevProfile["coins"];
  kol: RawFeed[];
  smart: RawFeed[];
  signals: RawSignal[];
  wallet: Omit<WalletProfile, "chain"> & { xFollowers?: number; fundFrom?: string };
  trending: BoardToken[];
  hot: BoardToken[];
}

export type FixtureFlags = { empty?: boolean; partial?: boolean };

function flagsFromStorage(): FixtureFlags {
  try {
    return {
      empty: globalThis.localStorage?.getItem("claudio.fixtures.empty") === "1",
      partial: globalThis.localStorage?.getItem("claudio.fixtures.partial") === "1",
    };
  } catch {
    return {};
  }
}

/** Fixture response for an /api/insights path, or null for "endpoint not available" (the client treats it as a 404). */
export function insightsFixture(fullPath: string, flags: FixtureFlags = flagsFromStorage(), now = Date.now()): unknown | null {
  if (flags.empty) return null;
  const url = new URL(fullPath, "http://x");
  const p = url.pathname;
  const q = url.searchParams;
  const shift = (sec: number) => now - Math.max(0, RAW.recordedAtSec - sec) * 1000 - 4_000;
  const timeShift = (ms: number | null | undefined) => (ms ? shift(ms / 1000) : ms ?? null);
  let m: RegExpMatchArray | null;

  if ((m = p.match(/^\/api\/insights\/token\/([^/]+)(\/[a-z]+)?$/))) {
    const key = decodeURIComponent(m[1]);
    const address = key.slice(key.indexOf(":") + 1);
    const sub = m[2] ?? "";
    if (sub === "") return tokenInsights(key, address, now, flags.partial === true);
    if (sub === "/holders") {
      const limit = Math.min(100, Math.max(20, Number(q.get("limit")) || 50));
      return { data: RAW.holders.slice(0, limit).map((h) => ({ ...h, firstSeenAt: timeShift(h.firstSeenAt), lastActiveAt: timeShift(h.lastActiveAt) })), updatedAt: now, source: "gmgn" };
    }
    if (sub === "/traders") {
      return { data: RAW.traders.map((h) => ({ ...h, firstSeenAt: timeShift(h.firstSeenAt), lastActiveAt: timeShift(h.lastActiveAt) })), updatedAt: now, source: "gmgn" };
    }
    if (sub === "/dev") return flags.partial ? null : devProfile(now);
    if (sub === "/scores") return scores();
    return null;
  }
  if ((m = p.match(/^\/api\/insights\/wallet\/([a-z]+)\/([^/]+)$/))) {
    const address = decodeURIComponent(m[2]);
    const known = [...RAW.holders, ...RAW.traders, ...RAW.kol.map((k) => ({ ...k.wallet })), ...RAW.smart.map((k) => ({ ...k.wallet }))].find((w) => w.address === address);
    const base = RAW.wallet;
    const profile: WalletProfile & { recent?: FeedTrade[] } = {
      ...base,
      chain: "sol",
      address,
      name: known ? known.name ?? null : base.name,
      twitter: known ? known.twitter ?? null : base.twitter,
      tags: known ? known.tags : base.tags,
      tools: known ? known.tools : base.tools,
      style: { title: known?.tags.includes("smart") ? "Patient swing trader" : "Fast flipper", subtitle: "Holds most coins for under an hour", badges: ["Early buyer", "Takes profit", "Trades daily"] },
      score: walletScore,
      review:
        "This wallet trades a lot of small positions and sells fast. Wins about 3 in 10 trades but the winners pay for the losers. Often among the first buyers of coins that later get KOL attention.",
      recent: RAW.kol.filter((k) => k.wallet.address === RAW.kol[0].wallet.address).slice(0, 8).map((k) => ({ ...k, wallet: { ...k.wallet, address }, at: shift(k.atSec) })),
    };
    return profile;
  }
  if (p === "/api/insights/feed/kol" || p === "/api/insights/feed/smart") {
    const rows = p.endsWith("kol") ? RAW.kol : RAW.smart;
    const side = q.get("side");
    return { data: rows.filter((r) => !side || r.side === side).map(({ atSec, ...r }) => ({ ...r, at: shift(atSec) })) };
  }
  if (p === "/api/insights/feed/signals") return { data: RAW.signals.map(({ atSec, ...s }) => ({ ...s, at: shift(atSec) })) };
  if (p === "/api/insights/trending" || p === "/api/insights/hot") {
    const rows = p.endsWith("hot") ? RAW.hot : RAW.trending;
    const interval = q.get("interval") ?? "1h";
    const order = interval === "5m" ? [...rows].sort((a, b) => b.change5mPct - a.change5mPct) : interval === "24h" ? [...rows].sort((a, b) => b.volume24hUsd - a.volume24hUsd) : rows;
    return { data: order.map((t, i) => ({ ...t, createdAt: now - (i + 1) * 47 * 60_000, updatedAt: now })) };
  }
  if (p === "/api/insights/status") {
    const s: InsightsStatus = {
      gmgn: { enabled: true, reason: null, ratePerSec: 3.2, maxRatePerSec: 5, queued: 4, pausedUntil: null, calls1m: 171, errors1m: 2, cacheEntries: 1_284, hitRate: 0.83 },
      liveTrades: { source: "pumpportal", watching: 12, pumpportal: { connected: true, keyed: false, subscribed: 12 }, alchemy: { configured: false, connected: false, subscribed: 0 } },
    };
    return s;
  }
  return null;
}

function tokenInsights(key: string, address: string, now: number, partial: boolean): TokenInsights {
  const i = RAW.insights;
  return {
    ...i,
    key,
    chain: "sol",
    address,
    signals: [
      { kind: "kol_buy", label: "KOL bought", at: now - 3 * 60_000, mcapUsd: i.stats.mcapUsd ?? null, detail: "Damian Prosalendis" },
      { kind: "smart_buy", label: "Smart money bought", at: now - 11 * 60_000, mcapUsd: (i.stats.mcapUsd ?? 0) * 0.92, detail: "3 wallets" },
      { kind: "dex_link", label: "DexScreener profile updated", at: now - 5 * 3_600_000, detail: null },
      { kind: "ath", label: "New ATH", at: now - 26 * 3_600_000, mcapUsd: 1_282_000, detail: null },
    ],
    security: partial ? null : i.security,
    dev: partial ? null : i.dev,
    source: "gmgn",
    updatedAt: now,
    partial: partial ? "GMGN is cooling down (rate limit); showing what we have" : null,
  };
}

